content.text:
{
  "pipeline_id": "protein-binder-design-validated",
  "name": "Protein Binder Design + Affinity Validation",
  "description": "End-to-end protein binder discovery pipeline using the Foundry (RFdiffusion3 + ProteinMPNN + RoseTTAFold3) for de novo binder generation, followed by Boltz-2 co-folding to validate and rank candidates by interface confidence (ipTM, pTM, pLDDT). NOTE: no numeric ΔG or Kd is produced — Boltz-2 scores affinity only for small-molecule binders, not protein-protein interfaces. Scores are computational predictions, not experimental measurements. Ideal for therapeutic antibody alternatives, research tools, and drug discovery.",
  "estimated_duration": "30-90 minutes",
  "inputs": [
    {
      "name": "targetProtein",
      "type": "string",
      "required": true,
      "description": "Target protein: PDB ID (e.g. 7CR5) or workspace file path (e.g. @structures/target.pdb)"
    },
    {
      "name": "bindingSite",
      "type": "string",
      "required": true,
      "description": "Optional: comma-separated residue positions defining the binding interface (e.g. '45,67,89,102')"
    },
    {
      "name": "binderLength",
      "type": "string",
      "required": false,
      "default": "80",
      "description": "Approximate binder length in residues"
    },
    {
      "name": "numDesigns",
      "type": "string",
      "required": false,
      "default": "5",
      "description": "Number of binder candidates to generate (1-10)"
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "protein-binder-design",
      "description": "De novo protein binder design with Foundry pipeline (RFdiffusion3 → ProteinMPNN → RoseTTAFold3 validation)"
    },
    {
      "step": 2,
      "tool": "binding-affinity-prediction",
      "description": "Co-fold each designed candidate with the target using Boltz-2 and score the interface — returns ipTM, pTM and pLDDT for ranking (no ΔG/Kd: Boltz-2 affinity requires a ligand binder)",
      "after": [
        "step1_design"
      ]
    }
  ]
}

