        "showWhen": {
          "parameter": "operation",
          "value": "search"
        }
      },
      {
        "name": "resolution_range",
        "type": "string",
        "required": false,
        "description": "Resolution range filter (e.g., 0.5-2.0)",
        "placeholder": "e.g., 0.5-2.0",
        "showWhen": {
          "parameter": "operation",
          "value": "search"
